    // يُستخدم فقط عند فشل الـ Pinning لجلب توجيهات التحديث أو إظهار شاشة Force Update
    val disasterRecoveryClient: OkHttpClient = OkHttpClient.Builder()
        .connectTimeout(10, TimeUnit.SECONDS)
