            primaryClient.newCall(request).execute()
        } catch (e: SSLPeerUnverifiedException) {
            // فشل التحقق من الشهادة! التحقق من دومين الطوارئ هل هناك تحديث إجباري للشهادات؟
            handlePinningFailure(e)
            throw e
        }
